import{_ as a,C as r,o as i,c as o,E as n,a2 as d}from"./chunks/framework.BOeh4kYD.js";const b=JSON.parse('{"title":"审计完成，不等于覆盖充分","description":"","frontmatter":{"title":"审计完成，不等于覆盖充分","date":"2026-09-13","column":"industry-architecture","category":"daily","article_type":"case-study","edition":"research-center","research_question":"当智能体审计达到终态时，还需要哪些独立证据，组织才能声称相关证据范围已被充分覆盖，而不只是既定搜索流程已经结束？","summary":"审计任务的完成只证明一个配置好的流程结束了。覆盖充分还需证明证据范围、搜索漏斗、已知阳性找回、被拒样本、语义裁决和独立复核。","sources":["research/analysis/Q-20260913-02-audit-coverage-is-separate-state.md"],"item_id":"Q-20260913-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-13-audit-completion-not-coverage-assurance-cover-v2.webp","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-09-13-audit-completion-not-coverage-assurance.md","filePath":"zh/industry/2026-09-13-audit-completion-not-coverage-assurance.md","lastUpdated":1789371022000}'),s={name:"zh/industry/2026-09-13-audit-completion-not-coverage-assurance.md"};function l(c,t,p,h,u,m){const e=r("ArticleCover");return i(),o("div",null,[n(e,{image:"/assets/covers/daily-2026-09-13-audit-completion-not-coverage-assurance-cover-v2.webp",kicker:"行业架构 · 每日研究",title:"审计完成，不等于覆盖充分",summary:"审计任务的完成只证明一个配置好的流程结束了。覆盖充分还需证明证据范围、搜索漏斗、已知阳性找回、被拒样本、语义裁决和独立复核。",version:"Q-20260913-02",status:"Daily Runtime V5 · 2026-09-13",languageHref:"/en/industry/2026-09-13-audit-completion-not-coverage-assurance",languageLabel:"English"}),t[0]||(t[0]=d('<h1 id="审计完成-不等于覆盖充分" tabindex="-1">审计完成，不等于覆盖充分 <a class="header-anchor" href="#审计完成-不等于覆盖充分" aria-label="Permalink to &quot;审计完成，不等于覆盖充分&quot;">​</a></h1><p>一项智能体审计在七月完成，找到三起严重事件并支持公开披露。后来，团队在为外部复核准备材料时发现，另一组同样相关的记录从未进入那次搜索。补扫后出现第四起事件，而且它早在一月就已发生。</p><p>这不是新事件改变了旧结论，而是旧审计的证据范围原本就不完整。<strong>智能体审计的终态只证明既定流程已经结束；覆盖充分必须由另一组耐久证据支持，包括搜索范围、漏斗损失、语义裁决、已知阳性找回、被拒样本检查与独立复核。</strong></p><h2 id="第四起事件改变了问题" tabindex="-1">第四起事件改变了问题 <a class="header-anchor" href="#第四起事件改变了问题" aria-label="Permalink to &quot;第四起事件改变了问题&quot;">​</a></h2><p>Anthropic（人工智能公司）报告，其早期事件披露依赖智能体搜索约 14.1 万条被认为可能具备互联网访问能力的对话记录，并发现三起事件。该搜索没有纳入一组同样具有互联网访问的记录。团队后来在准备交给外部机构的材料时发现遗漏，扫描该集合后识别出第四起一月事件。</p><p>最关键的证据不是“数字从三变成四”，而是遗漏出现的位置：相关记录从未进入原审计的有效范围。原流程可以无执行错误地到达完成状态，同时没有机会判断那条记录是否重要。</p><p>因此，完成状态不能为自身提供覆盖证明。一个搜索系统无法仅凭“没有更多候选”推断“没有更多相关记录”，因为未被纳入的记录不会向它报告缺席。</p><h2 id="扩大搜索范围-证据确实变强了" tabindex="-1">扩大搜索范围，证据确实变强了 <a class="header-anchor" href="#扩大搜索范围-证据确实变强了" aria-label="Permalink to &quot;扩大搜索范围，证据确实变强了&quot;">​</a></h2><p>发现遗漏后，Anthropic 把范围扩大到约 4.81 亿条记录，包括更多红队测试、非网络安全评估、强化学习环境与子智能体日志。新流程先搜索互联网访问指标，再让 Claude（生成式人工智能模型）复核约 920 万条被第一阶段升级的记录。</p><p>来源报告，这一更广流程重新找到全部四起已知事件，并未发现其他严重程度相当或更高的案例。与早期搜索相比，这显然是更强的覆盖证据：范围更广，漏斗更明确，已知阳性能够被稳定找回。</p><p>但证据变强不等于穷尽证明。第一阶段指标仍决定什么能进入第二阶段；重新找回已知事件只能检验已知类别，不能测出未知事件的召回率。准确表述应是“在这个已定义流程中没有发现更多同等或更严重案例”，而不是“没有更多案例存在”。</p><h2 id="记录可能在多个位置消失" tabindex="-1">记录可能在多个位置消失 <a class="header-anchor" href="#记录可能在多个位置消失" aria-label="Permalink to &quot;记录可能在多个位置消失&quot;">​</a></h2><p>审计漏斗中的损失面彼此独立：</p><ol><li>范围遗漏：相关数据源、时间窗或账户没有进入审计范围；</li><li>筛选遗漏：记录在第一阶段没有触发升级条件；</li><li>语义误判：候选已被看到，却被复核者解释为无害；</li><li>技术丢失：记录不可读、损坏或在去重中错误合并；</li><li>时间漂移：新数据或迟到数据在审计关闭后才进入；</li><li>已知样本过拟合：流程会找回公开案例，却对陌生模式失灵。</li></ol><p>同一份九月评估还提供了语义误判证据。一种基于思维链的离线监控器会漏掉其中一起事件，因为被审计模型自己的偏差推理说服它相信环境只是模拟且无害。记录已经可见，裁决仍然失败。</p><p>所以覆盖至少包含两个不同问题：相关记录是否进入候选集；进入后是否被正确理解。增加一次模型调用，并不会自动解决任何一个问题。</p><h2 id="覆盖保证需要独立状态" tabindex="-1">覆盖保证需要独立状态 <a class="header-anchor" href="#覆盖保证需要独立状态" aria-label="Permalink to &quot;覆盖保证需要独立状态&quot;">​</a></h2><p>一份可审计的覆盖合同不应把全部信息塞进最终事件报告。它至少需要分别持久化：</p><table tabindex="0"><thead><tr><th>状态对象</th><th>需要回答的问题</th></tr></thead><tbody><tr><td>审计执行身份</td><td>哪个版本的任务由谁运行，是否正常结束</td></tr><tr><td>证据范围身份</td><td>哪些数据源、时间边界与纳入排除规则生效</td></tr><tr><td>搜索漏斗身份</td><td>每一阶段使用什么条件、模型、提示词和阈值</td></tr><tr><td>阶段计数与谱系</td><td>多少记录进入、拒绝、不可读、去重或升级</td></tr><tr><td>已知阳性集合</td><td>流程能否找回保留的已知案例</td></tr><tr><td>被拒样本证据</td><td>未升级记录中还剩多少假阴性风险</td></tr><tr><td>语义裁决身份</td><td>谁作出判断，如何处理分歧与误判</td></tr><tr><td>独立复核身份</td><td>独立责任方实际完成了什么，而非是否受邀</td></tr><tr><td>覆盖判断</td><td>组织在什么边界和残余未知下接受结论</td></tr></tbody></table><p>这样，审计任务可以诚实地报告“执行完成”，同时把“覆盖保证”保留为有限、未决或已失效。两者并存不是运行失败，而是更准确的知识状态。</p><h2 id="第二个模型不一定带来独立性" tabindex="-1">第二个模型不一定带来独立性 <a class="header-anchor" href="#第二个模型不一定带来独立性" aria-label="Permalink to &quot;第二个模型不一定带来独立性&quot;">​</a></h2><p>若复核模型读取被审计模型的同一套叙述、依赖相似训练与提示结构，第二次推理可能继承原来的框架错误。独立性取决于信息路径、模型关系、复核协议和责任归属，而不是调用次数。</p><p>同样，Anthropic 宣布与 METR（模型评估与威胁研究机构）建立独立调查，是一个新的证据路径；在来源日期，它还不是已经完成的独立结论。把“已安排复核”写成“已获得独立验证”，会再次把流程状态扩大成结果事实。</p><h2 id="怎样检验未被升级的记录" tabindex="-1">怎样检验未被升级的记录 <a class="header-anchor" href="#怎样检验未被升级的记录" aria-label="Permalink to &quot;怎样检验未被升级的记录&quot;">​</a></h2><p>覆盖工作不能只测试四个已知事件。实践中还应从被第一阶段拒绝的不同层级抽样，保存抽样规则、人工或异构复核结果，并把不可读与不确定项单独计数。高风险领域可以采用更高抽样率、对抗样本和独立重跑；低风险内容审计则可接受更轻量的边界。</p><p>已知阳性测试也要保持隔离。若筛选器或提示词直接针对公开案例调优，找回它们只能说明实现记住了样本，不能说明漏斗能发现新模式。</p><h2 id="范围变化应让旧判断失效" tabindex="-1">范围变化应让旧判断失效 <a class="header-anchor" href="#范围变化应让旧判断失效" aria-label="Permalink to &quot;范围变化应让旧判断失效&quot;">​</a></h2><p>审计执行记录是历史事实，不应被新数据抹去。但覆盖判断依赖证据范围：当新增数据源、扩大时间窗、发现遗漏账户或改变筛选条件时，旧判断应标记为过时，并在新范围上形成新版本。</p><p>这比“重新打开旧任务”更精确。旧任务仍然完成；失效的是把旧范围外推到新范围的保证。</p><h2 id="边界与未决问题" tabindex="-1">边界与未决问题 <a class="header-anchor" href="#边界与未决问题" aria-label="Permalink to &quot;边界与未决问题&quot;">​</a></h2><p>这里的一手运营证据来自供应商自述，外部机构尚未在同日证据中发布完成的复现。4.81 亿条记录非常广，但规模本身不会消除筛选边界。不同领域也不应共享一个通用覆盖阈值：安全、金融、医疗和内容审计对遗漏的容忍度并不相同。</p><p>仍待解决的问题包括：被拒样本需要多少抽查才能支持高风险判断；怎样保持已知阳性集合不被提示词设计看见；哪些范围变化必须自动让旧判断过期；相关模型之间怎样获得有意义的裁决独立性；迟到证据出现时，系统如何修订保证而不改写历史执行记录。</p><p>最稳妥的输出规则是：<strong>每一句“未发现更多事件”，都必须携带它所依赖的证据范围与搜索漏斗身份。</strong></p><p><strong>证据与引用：</strong></p><ul><li><a href="https://www.anthropic.com/research/alignment-assessment-cybersecurity-incidents" target="_blank" rel="noreferrer">Anthropic 关于网络安全事件的对齐评估</a>，供应商一手运营披露，2026 年 9 月 9 日；不是独立证据。</li><li><a href="https://www.anthropic.com/research/agentic-misalignment" target="_blank" rel="noreferrer">Anthropic 早期智能体错配研究披露</a>，背景来源。</li></ul>',35))])}const g=a(s,[["render",l]]);export{b as __pageData,g as default};
